// B1–B4 read-only library. Workspace/checklist state stays in the existing app.
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const api=window.LIMI_API_BASE??'/api/legal';
const groups={tax:'Thuế',accounting:'Kế toán',labor:'Lao động',insurance:'Bảo hiểm',company:'Doanh nghiệp',commerce:'Thương mại',data:'Dữ liệu',fire:'PCCC',environment:'Môi trường',food:'An toàn thực phẩm'};
let change=()=>{},open=()=>{},requestKey='',result=null,failure='',controller;
const params=()=>new URLSearchParams(location.search);
const link=(updates)=>{const p=params();p.set('view','laws');for(const [k,v]of Object.entries(updates)){if(v===null)p.delete(k);else p.set(k,String(v));}return `${location.pathname}?${p}`;};
const get=async(path,signal)=>{const r=await fetch(api+path,{signal,cache:'no-store'});if(!r.ok)throw Error(r.status===404?'Không tìm thấy văn bản hoặc phiên bản đã chọn.':'Chưa tải được dữ liệu luật. Bạn có thể thử lại.');return r.json();};
function navigate(url){history.pushState(null,'',url);requestKey='';result=null;failure='';open();window.scrollTo({top:0,behavior:'instant'});}
export function openLawSearch(q=''){navigate(link({law:null,snapshotId:null,parseRunId:null,provision:null,q:q||null,page:1}));}
export function configureRealLibrary(onChange,onOpen){change=onChange;open=onOpen;
  document.addEventListener('click',e=>{const a=e.target.closest('[data-real-link]');if(a){e.preventDefault();navigate(a.getAttribute('href'));}
    const search=e.target.closest('[data-find-law]');if(search){e.preventDefault();openLawSearch(search.dataset.findLaw);}
    if(e.target.closest('[data-real-retry]')){requestKey='';result=null;failure='';change();}});
  document.addEventListener('submit',e=>{if(e.target.id!=='real-law-search')return;e.preventDefault();const values=new FormData(e.target);navigate(link({law:null,snapshotId:null,parseRunId:null,provision:null,page:1,q:values.get('q')||null,scope:values.get('scope')||null,group:values.get('group')||null}));});
  window.addEventListener('popstate',()=>{requestKey='';result=null;failure='';if(params().get('view')==='laws')open();});
}
export function renderRealLibrary(){
  const p=params(),law=p.get('law');
  const heading=`<div class="page-title" data-real-library><div><p class="eyebrow">THƯ VIỆN PHÁP LUẬT</p><h1>${law?'Đọc văn bản':'Tra cứu văn bản'}</h1><p>Nguồn luật toàn quốc, toàn văn và biểu mẫu trong cùng không gian làm việc.</p></div></div>`;
  const notice='';
  const filters=law?'':`<form id="real-law-search" class="real-filters"><label>Số hoặc tên văn bản<input name="q" value="${esc(p.get('q'))}" maxlength="200" placeholder="Ví dụ: 10/2020/TT-BLĐTBXH"></label><label>Phạm vi<select name="scope"><option value="">Tất cả</option><option value="NATIONAL" ${p.get('scope')==='NATIONAL'?'selected':''}>Toàn quốc</option></select></label><label>Lĩnh vực<select name="group"><option value="">Tất cả</option>${Object.entries(groups).map(([v,t])=>`<option value="${v}" ${p.get('group')===v?'selected':''}>${t}</option>`).join('')}</select></label><button class="primary-button" type="submit">Tìm văn bản</button></form>`;
  if(failure)return heading+notice+filters+`<div class="empty-state" role="alert"><h2>${esc(failure)}</h2><button class="secondary-button" data-real-retry>Thử lại</button><a class="text-action" data-real-link href="${esc(link({law:null,snapshotId:null,parseRunId:null,provision:null}))}">Về danh sách</a></div>`;
  if(!result)return heading+notice+filters+`<div class="empty-state" role="status">Đang tải dữ liệu…</div>`;
  if(!law){const {list}=result;return heading+notice+filters+`<div class="section-heading real-list-summary"><p>${list.total} văn bản · Trang ${list.page}</p><span class="real-tag">Dữ liệu đã lưu trên hệ thống</span></div><div class="legal-grid">${list.items.map(d=>`<article class="legal-card"><div class="legal-card-top"><span class="legal-type">${esc(d.documentNumber)}</span><span class="real-tag">${d.scope==='HUNG_YEN'?'Địa phương':'Toàn quốc'}</span>${d.quality.parseQuality?.requiresOcrTextReview?'<span class="real-tag ocr">Cần kiểm tra OCR</span>':''}</div><h2><a data-real-link href="${esc(link({law:d.id,snapshotId:null,provision:null,parseRunId:null}))}">${esc(d.title)}</a></h2><p>${esc(d.metadata.issuingBody??'Chưa xác định cơ quan ban hành')}</p><div class="legal-card-bottom"><span>Chờ thẩm định pháp lý · ${esc(groups[d.group]??d.group)}</span><a class="legal-link" data-real-link href="${esc(link({law:d.id,snapshotId:null,provision:null,parseRunId:null}))}">Đọc toàn văn và nguồn →</a></div></article>`).join('')||'<div class="empty-state">Không tìm thấy văn bản phù hợp. Hãy thử từ khóa hoặc bộ lọc khác.</div>'}</div><nav class="real-pagination" aria-label="Chuyển trang">${list.page>1?`<a class="secondary-button" data-real-link href="${esc(link({page:list.page-1}))}">← Trang trước</a>`:''}${list.page*list.pageSize<list.total?`<a class="secondary-button" data-real-link href="${esc(link({page:list.page+1}))}">Trang sau →</a>`:''}</nav>`;}
  const {detail:d,content:c,attachments,versions,provisions,selected}=result;
  const fileUrl=a=>api+a.downloadUrl.replace('/api/v1','');
  const base={law,snapshotId:c.snapshotId,parseRunId:null,provision:null};
  return `<a class="text-action" data-real-link href="${esc(link({law:null,snapshotId:null,parseRunId:null,provision:null}))}">← Về danh sách văn bản</a>${heading}<section class="real-law-title"><span class="legal-type">${esc(d.documentNumber)} · ${d.scope==='HUNG_YEN'?'Địa phương':'Toàn quốc'}</span><h2>${esc(d.title)}</h2><p>${esc(d.metadata.issuingBody??'Chưa xác định cơ quan ban hành')}</p></section>${notice}${c.quality.parseQuality?.requiresOcrTextReview?'<div class="disclaimer-banner real-ocr"><strong>Nội dung được nhận dạng bằng OCR — cần kiểm tra với bản gốc.</strong></div>':''}<div class="real-detail-grid"><section class="legal-card"><h2>Nguồn đối chiếu</h2><ul>${d.sources.map(s=>`<li><a href="${esc(s.source.url)}" target="_blank" rel="noopener noreferrer">${esc(s.source.domain)} — ${s.role==='CONTENT'?'Nội dung':'Thông tin văn bản'}</a></li>`).join('')}</ul><h3>Phiên bản đã lưu</h3><div class="real-versions">${versions.items.map((s,i)=>`<a data-real-link href="${esc(link({...base,snapshotId:s.id}))}">Bản ${i+1} · ${esc(new Date(s.createdAt).toLocaleDateString('vi-VN'))}</a>`).join('')}</div></section><section class="legal-card"><h2>Tệp gốc và biểu mẫu (${attachments.total})</h2><ul>${attachments.items.map(a=>`<li>${a.status==='AVAILABLE'?`<a href="${esc(fileUrl(a))}">${esc(a.provenance.filename??a.role)}</a>`:`${esc(a.provenance.filename??a.role)} — Chưa sẵn sàng`}${a.hasExtractedText?' <small>· Đã trích nội dung</small>':''}</li>`).join('')}</ul></section></div><section class="legal-card real-provisions"><h2>Điều luật (${provisions.total})</h2><ol>${provisions.items.map(n=>`<li><a data-real-link href="${esc(link({...base,parseRunId:provisions.parseRun.id,provision:n.id}))}">Điều ${esc(n.ordinal)} ${esc(n.heading)}</a>${n.quotedAmendmentCandidate?' <small>· Trích sửa đổi</small>':''}</li>`).join('')}</ol>${provisions.total>100?'<p>Hiển thị 100 điều đầu; toàn văn bên dưới giữ đầy đủ nội dung.</p>':''}</section><section class="legal-card real-content"><h2>${selected?'Trích dẫn đã chọn':'Toàn văn'}</h2>${selected?`<a data-real-link href="${esc(link(base))}">Đọc lại toàn văn</a>`:''}<p class="real-citation">Phiên bản ${esc(c.snapshotId)}${selected?` · Parse ${esc(provisions.parseRun.id)} · Mục ${esc(selected.externalNodeId)}`:''}</p><pre>${esc(selected?.text??c.fullText)}</pre></section>`;
}
export function mountRealLibrary(){
  if(!document.querySelector('[data-real-library]'))return;
  const p=params(),key=p.toString();if(key===requestKey)return;requestKey=key;controller?.abort();controller=new AbortController();const signal=controller.signal;
  const law=p.get('law'),query=new URLSearchParams();if(p.get('snapshotId'))query.set('snapshotId',p.get('snapshotId'));
  const load=async()=>{if(!law){const q=new URLSearchParams({page:p.get('page')??'1',pageSize:'20'});for(const name of ['q','group','scope'])if(p.get(name))q.set(name,p.get(name));return {list:await get(`/laws?${q}`,signal)};}
    const base=`/laws/${encodeURIComponent(law)}`;const [detail,content,attachments,versions,provisions]=await Promise.all([get(`${base}?${query}`,signal),get(`${base}/content?${query}`,signal),get(`${base}/attachments?${query}&pageSize=100`,signal),get(`${base}/snapshots`,signal),get(`${base}/provisions?${query}&nodeType=DIEU&pageSize=100`,signal)]);
    const selected=p.get('provision')?await get(`${base}/provisions/${encodeURIComponent(p.get('provision'))}?snapshotId=${content.snapshotId}&parseRunId=${encodeURIComponent(p.get('parseRunId')??'')}`,signal):null;return {detail,content,attachments,versions,provisions,selected};};
  load().then(data=>{if(signal.aborted||requestKey!==key)return;result=data;failure='';if(document.querySelector('[data-real-library]'))change();}).catch(e=>{if(signal.aborted)return;failure=/^(Không tìm thấy|Chưa tải được)/.test(e.message)?e.message:'Chưa tải được dữ liệu luật. Kiểm tra kết nối rồi thử lại.';result=null;if(document.querySelector('[data-real-library]'))change();});
}
